 90 | /**
 91 |  * Main entry point
 92 |  */
 93 | function main(): void {
 94 |   const port = process.env.PORT ? parseInt(process.env.PORT, 10) : 3000;
 95 | 
 96 |   const app = createProductionApp();
 97 | 
 98 |   // Start the server
 99 |   Bun.serve({
100 |     fetch: app.fetch,
101 |     port,
102 |   });
103 | 
104 |   console.log(`
105 | ${colors.bright}╔══════════════════════════════════════════════════╗${colors.reset}
106 | ${colors.bright}║     AInvest Stock Chart - Production Server      ║${colors.reset}
107 | ${colors.bright}╚══════════════════════════════════════════════════╝${colors.reset}
108 | 
109 | ${colors.green}Server running at:${colors.reset} ${colors.cyan}http://localhost:${port}${colors.reset}
110 | 
111 | ${colors.dim}Endpoints:${colors.reset}
112 |   ${colors.yellow}API:${colors.reset}      http://localhost:${port}/api/stock/AMD/quote
113 |   ${colors.yellow}Health:${colors.reset}   http://localhost:${port}/health
114 |   ${colors.yellow}App:${colors.reset}      http://localhost:${port}/
115 | 
116 | ${colors.dim}Press Ctrl+C to stop${colors.reset}
117 | `);
118 | }
119 | 
120 | // Set up signal handlers for graceful shutdown
121 | process.on('SIGINT', () => {
122 |   console.log(`\n${colors.yellow}Shutting down gracefully...${colors.reset}`);
123 |   process.exit(0);
124 | });
125 | 
126 | process.on('SIGTERM', () => {
127 |   console.log(`\n${colors.yellow}Shutting down gracefully...${colors.reset}`);
128 |   process.exit(0);
129 | });
130 | 
131 | // Run the server
132 | main();
