/**
 * Production Start Script
 * Serves the built frontend and API from a single Hono server
 * Handles static files and SPA fallback routing
 */

import { Hono } from 'hono';
import { cors } from 'hono/cors';
import { serveStatic } from 'hono/bun';
import stockRoutes from '../src/server/routes/stock.js';

// Color codes for terminal output
const colors = {
  reset: '\x1b[0m',
  bright: '\x1b[1m',
  green: '\x1b[32m',
  cyan: '\x1b[36m',
  yellow: '\x1b[33m',
  dim: '\x1b[2m',
  red: '\x1b[31m',
};

/**
 * Create the production Hono app
 * Combines API routes with static file serving
 */
function createProductionApp(): Hono {
  const app = new Hono();

  // Configure CORS
  app.use(
    '*',
    cors({
      origin: '*',
      allowMethods: ['GET', 'POST', 'OPTIONS'],
      allowHeaders: ['Content-Type', 'Authorization'],
      maxAge: 86400,
    })
  );

  // Health check endpoint
  app.get('/health', (c) => {
    return c.json({ status: 'ok', timestamp: Date.now() });
  });

  // Mount stock API routes at /api/stock
  app.route('/api/stock', stockRoutes);

  // 404 handler for API routes
  app.notFound((c) => {
    // If it's an API request, return JSON error
    if (c.req.path.startsWith('/api')) {
      return c.json({ error: 'Not Found', code: 404 }, 404);
    }
    // Otherwise fall through to SPA
    return c.html('');
  });

  // Error handler
  app.onError((err, c) => {
    console.error('Server error:', err);
    if (c.req.path.startsWith('/api')) {
      return c.json({ error: 'Internal Server Error', code: 500 }, 500);
    }
    return c.html('');
  });

  // Resolve dist path relative to project root
  const distPath = import.meta.dir + '/../dist';

  // Serve static files from dist folder (for assets, js, css, etc.)
  app.use('/assets/*', serveStatic({ root: distPath }));
  app.use('/favicon.svg', serveStatic({ root: distPath }));

  // SPA fallback: serve index.html for all non-API routes
  app.get('*', async (c) => {
    try {
      const file = Bun.file(distPath + '/index.html');
      if (await file.exists()) {
        const html = await file.text();
        return c.html(html);
      }
      return c.text('index.html not found. Please run "bun run build" first.', 500);
    } catch (error) {
      console.error('Error serving index.html:', error);
      return c.text('Error serving application', 500);
    }
  });

  return app;
}

/**
 * Main entry point
 */
function main(): void {
  const port = process.env.PORT ? parseInt(process.env.PORT, 10) : 3000;

  const app = createProductionApp();

  // Start the server
  Bun.serve({
    fetch: app.fetch,
    port,
  });

  console.log(`
${colors.bright}╔══════════════════════════════════════════════════╗${colors.reset}
${colors.bright}║     AInvest Stock Chart - Production Server      ║${colors.reset}
${colors.bright}╚══════════════════════════════════════════════════╝${colors.reset}

${colors.green}Server running at:${colors.reset} ${colors.cyan}http://localhost:${port}${colors.reset}

${colors.dim}Endpoints:${colors.reset}
  ${colors.yellow}API:${colors.reset}      http://localhost:${port}/api/stock/AMD/quote
  ${colors.yellow}Health:${colors.reset}   http://localhost:${port}/health
  ${colors.yellow}App:${colors.reset}      http://localhost:${port}/

${colors.dim}Press Ctrl+C to stop${colors.reset}
`);
}

// Set up signal handlers for graceful shutdown
process.on('SIGINT', () => {
  console.log(`\n${colors.yellow}Shutting down gracefully...${colors.reset}`);
  process.exit(0);
});

process.on('SIGTERM', () => {
  console.log(`\n${colors.yellow}Shutting down gracefully...${colors.reset}`);
  process.exit(0);
});

// Run the server
main();
